R=Path(__file__).resolve().parent;p=argparse.ArgumentParser();p.add_argument('--results',required=True);a=p.parse_args();j=json.loads(Path(a.results).read_text());assert j['complete'];m=j['manifest'];rows=j['rows'];D=R.parents[2]/'sites/bam-mudd-head-activation-20261023/dist/shorttrain/no-self-readout/mudd-spectral/softmax-precision';A=D/'assets';A.mkdir(parents=True,exist_ok=True)
