def table(headers,data):return '<div class="scroll"><table><tr>'+''.join('<th>'+html.escape(h)+'</th>' for h in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in data)+'</table></div>'
tab=[];details=[]
for t in steps:
 r=rows[str(t)];bf=r['variants']['CE_pax_bf16'];v=bf['delta'];tab.append([f'{t//1000}k',f"{r['old_FP32']['mean']:.7f}",f"{bf['loss']['mean']:.7f}",f"{v['mean']:+.7f} [{v['ci95'][0]:+.7f},{v['ci95'][1]:+.7f}]",f"{r['serial_minus_old_native_FP32_gap']['mean']:+.7f}",f"{bf['ratio_to_native_FP32_gap']:.2%}"])
 for k,label in [('CE_pax_bf16','Praxis只移除FP32转换'),('CE_maxtext_train','MaxText训练CE前传'),('CE_strict_bf16','额外强制落盘BF16 log-probs'),('CE_bf16_renormalized','上述BF16 log-probs再FP32归一化')]:
  v=r['variants'][k];details.append([f'{t//1000}k',label,f"{v['loss']['mean']:.7f}",f"{v['delta']['mean']:+.7f}",f"{v['remaining_gap_after_change']['mean']:+.7f}"])
